-- Taxonomy v2: the approved Unit > Macro > Micro names from supabase/data/taxonomy_v2.csv.
-- Additive only: existing rows and questions are not changed. The question trigger
-- (00013) accepts a question only when its names exist here, so this must run before
-- the new catalog is used for import. Safe to run more than once.
-- Remapping existing questions from the old unit codes is a separate step (not in this file).

ON CONFLICT (exam_group, unit_name, macro_topic_name, micro_topic_name) DO UPDATE
SET active = true;
